package sqlite

import (
	"fmt"
	"testing"
	"testing/fstest"

	"github.com/pressly/goose/v3"
)

func TestMigrateRepairsAgentInstallJobsFromLegacyVersions(t *testing.T) {
	for _, legacyVersion := range []int64{119, 120} {
		t.Run(fmt.Sprintf("version_%d", legacyVersion), func(t *testing.T) {
			db := openMigratedDatabaseCopy(t, 118)

			contents, err := migrationsFS.ReadFile("migrations/0123_agent_install_jobs.sql")
			if err != nil {
				t.Fatalf("read agent install jobs migration: %v", err)
			}
			gooseMu.Lock()
			goose.SetBaseFS(fstest.MapFS{
				fmt.Sprintf("migrations/%04d_agent_install_jobs.sql", legacyVersion): &fstest.MapFile{Data: contents},
			})
			goose.SetLogger(goose.NopLogger())
			if err := goose.SetDialect("sqlite3"); err != nil {
				gooseMu.Unlock()
				t.Fatalf("set goose dialect: %v", err)
			}
			if err := goose.Up(db, "migrations"); err != nil {
				gooseMu.Unlock()
				t.Fatalf("apply legacy agent install migration: %v", err)
			}
			gooseMu.Unlock()

			if err := migrate(db); err != nil {
				t.Fatalf("migrate legacy agent install database: %v", err)
			}

			for _, version := range []int64{119, 120, 123} {
				var applied int
				if err := db.QueryRow(`
SELECT COALESCE((
    SELECT is_applied FROM goose_db_version
    WHERE version_id = ? ORDER BY id DESC LIMIT 1
), 0)`, version).Scan(&applied); err != nil {
					t.Fatalf("read migration %d: %v", version, err)
				}
				if applied != 1 {
					t.Fatalf("migration %d applied = %d, want 1", version, applied)
				}
			}
			var tableCount int
			if err := db.QueryRow(
				`SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = 'agent_install_jobs'`,
			).Scan(&tableCount); err != nil {
				t.Fatalf("read agent_install_jobs table: %v", err)
			}
			if tableCount != 1 {
				t.Fatalf("agent_install_jobs table count = %d, want 1", tableCount)
			}
		})
	}
}

package store_test

import (
	"context"
	"testing"
	"time"

	"github.com/aoagents/agent-orchestrator/backend/internal/ports"
	"github.com/aoagents/agent-orchestrator/backend/internal/storage/sqlite/sqlitetest"
)

func TestAgentInstallJobStoreRoundTripAndList(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	store := sqlitetest.MustOpen(t)
	started := time.Date(2026, 8, 31, 10, 0, 0, 0, time.UTC)
	finished := started.Add(time.Minute)
	want := ports.AgentInstallJobRecord{
		Target: "codex", Status: "failed", Method: "npm", Command: "npm install -g @openai/codex",
		ExpectedDestination: "/Users/test/.npm/bin/codex", Output: "permission denied", Error: "exit status 1",
		StartedAt: started, FinishedAt: &finished, UpdatedAt: finished,
	}

	if err := store.UpsertAgentInstallJob(ctx, want); err != nil {
		t.Fatalf("upsert job: %v", err)
	}
	got, ok, err := store.GetAgentInstallJob(ctx, "codex")
	if err != nil {
		t.Fatalf("get job: %v", err)
	}
	if !ok {
		t.Fatal("get job: missing record")
	}
	assertAgentInstallJobRecord(t, got, want)

	jobs, err := store.ListAgentInstallJobs(ctx)
	if err != nil {
		t.Fatalf("list jobs: %v", err)
	}
	if len(jobs) != 1 {
		t.Fatalf("list jobs length = %d, want 1", len(jobs))
	}
	assertAgentInstallJobRecord(t, jobs[0], want)
}

func TestInterruptActiveAgentInstallJobs(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	store := sqlitetest.MustOpen(t)
	started := time.Date(2026, 8, 31, 10, 0, 0, 0, time.UTC)
	for _, record := range []ports.AgentInstallJobRecord{
		{Target: "codex", Status: "installing", Method: "npm", StartedAt: started, UpdatedAt: started},
		{Target: "claude-code", Status: "verifying", Method: "homebrew", StartedAt: started, UpdatedAt: started},
		{Target: "cursor", Status: "succeeded", Method: "manual", StartedAt: started, UpdatedAt: started},
	} {
		if err := store.UpsertAgentInstallJob(ctx, record); err != nil {
			t.Fatalf("seed %s: %v", record.Target, err)
		}
	}

	interruptedAt := started.Add(2 * time.Minute)
	if err := store.InterruptActiveAgentInstallJobs(ctx, interruptedAt); err != nil {
		t.Fatalf("interrupt active jobs: %v", err)
	}

	jobs, err := store.ListAgentInstallJobs(ctx)
	if err != nil {
		t.Fatalf("list jobs: %v", err)
	}
	byTarget := make(map[string]ports.AgentInstallJobRecord, len(jobs))
	for _, job := range jobs {
		byTarget[job.Target] = job
	}
	for _, target := range []string{"codex", "claude-code"} {
		job := byTarget[target]
		if job.Status != "interrupted" {
			t.Errorf("%s status = %q, want interrupted", target, job.Status)
		}
		if job.FinishedAt == nil || !job.FinishedAt.Equal(interruptedAt) {
			t.Errorf("%s finishedAt = %v, want %v", target, job.FinishedAt, interruptedAt)
		}
		if job.Error == "" {
			t.Errorf("%s error is empty", target)
		}
	}
	if got := byTarget["cursor"].Status; got != "succeeded" {
		t.Errorf("cursor status = %q, want succeeded", got)
	}
}

func assertAgentInstallJobRecord(t *testing.T, got, want ports.AgentInstallJobRecord) {
	t.Helper()
	if got.Target != want.Target || got.Status != want.Status || got.Method != want.Method || got.Command != want.Command ||
		got.ExpectedDestination != want.ExpectedDestination || got.Output != want.Output || got.Error != want.Error ||
		!got.StartedAt.Equal(want.StartedAt) || !got.UpdatedAt.Equal(want.UpdatedAt) {
		t.Fatalf("job = %#v, want %#v", got, want)
	}
	if (got.FinishedAt == nil) != (want.FinishedAt == nil) {
		t.Fatalf("finishedAt = %v, want %v", got.FinishedAt, want.FinishedAt)
	}
	if got.FinishedAt != nil && !got.FinishedAt.Equal(*want.FinishedAt) {
		t.Fatalf("finishedAt = %v, want %v", got.FinishedAt, want.FinishedAt)
	}
}

package claudecode

import (
	"context"
	"fmt"
	"testing"
	"time"

	"github.com/aoagents/agent-orchestrator/backend/internal/ports"
	"github.com/aoagents/agent-orchestrator/backend/pkg/agentcreds"
)

func TestAuthCacheRequiresTheCurrentCredentialAndSupportsInvalidation(t *testing.T) {
	now := time.Date(2026, 9, 16, 0, 0, 0, 0, time.UTC)
	cache := newAuthCache(time.Minute)
	cache.now = func() time.Time { return now }
	credential := agentcreds.Credential{Kind: agentcreds.KindAPIKey, Secret: "working"}
	result := agentcreds.Result{
		State: agentcreds.StateValid, Provider: agentcreds.ProviderFirstParty,
		Fingerprint: credential.Fingerprint(), CheckedAt: now,
	}

	cache.put(result)
	if _, ok := cache.get(credential.Fingerprint(), agentcreds.ProviderFirstParty); !ok {
		t.Fatal("current credential should reuse its cached verdict")
	}
	other := agentcreds.Credential{Kind: agentcreds.KindAPIKey, Secret: "replacement"}
	if _, ok := cache.get(other.Fingerprint(), agentcreds.ProviderFirstParty); ok {
		t.Fatal("a replacement credential must not reuse the previous verdict")
	}
	if _, ok := cache.get(credential.Fingerprint(), agentcreds.ProviderBedrock); ok {
		t.Fatal("a different provider must not reuse the previous verdict")
	}
	cache.invalidate()
	if _, ok := cache.get(credential.Fingerprint(), agentcreds.ProviderFirstParty); ok {
		t.Fatal("runtime rejection must invalidate the cached verdict")
	}
}

func TestAuthCacheUsesShortTTLForNegativeAndInconclusiveResults(t *testing.T) {
	now := time.Date(2026, 9, 16, 0, 0, 0, 0, time.UTC)
	cache := newAuthCache(time.Minute)
	cache.now = func() time.Time { return now }
	credential := agentcreds.Credential{
		Kind: agentcreds.KindAPIKey, Secret: "working", Provider: agentcreds.ProviderFirstParty,
	}
	fingerprint := credential.Fingerprint()

	for _, state := range []agentcreds.State{agentcreds.StateInvalid, agentcreds.StateUnknown} {
		cache.put(agentcreds.Result{State: state, Provider: agentcreds.ProviderFirstParty, Fingerprint: fingerprint})
		if _, ok := cache.get(fingerprint, agentcreds.ProviderFirstParty); !ok {
			t.Fatalf("%s result should be reused briefly", state)
		}
		now = now.Add(30*time.Second + time.Nanosecond)
		if _, ok := cache.get(fingerprint, agentcreds.ProviderFirstParty); ok {
			t.Fatalf("%s result should expire after 30 seconds", state)
		}
	}
	cache.put(agentcreds.Result{State: agentcreds.StateValid, Provider: agentcreds.ProviderFirstParty, Fingerprint: fingerprint})
	now = now.Add(time.Minute + time.Nanosecond)
	if _, ok := cache.get(fingerprint, agentcreds.ProviderFirstParty); ok {
		t.Fatal("expired verdict must not be reused")
	}
}

func TestAuthCacheDoesNotStoreResultsWithoutAStableFingerprint(t *testing.T) {
	cache := newAuthCache(time.Minute)
	cache.put(agentcreds.Result{State: agentcreds.StateInvalid, Provider: agentcreds.ProviderFirstParty})
	if cache.entry != nil {
		t.Fatal("a result without a credential fingerprint must not be cached")
	}
}

func TestAuthCacheDoesNotStoreAProbeItsCallerCanceled(t *testing.T) {
	cache := newAuthCache(time.Minute)
	credential := agentcreds.Credential{Kind: agentcreds.KindAPIKey, Secret: "working"}
	canceled := fmt.Errorf("Get \"https://api.anthropic.com/v1/models\": %w", context.Canceled)
	cache.put(agentcreds.Result{
		State: agentcreds.StateUnknown, Provider: agentcreds.ProviderFirstParty,
		Fingerprint: credential.Fingerprint(), Err: canceled,
	})
	if _, ok := cache.get(credential.Fingerprint(), agentcreds.ProviderFirstParty); ok {
		t.Fatal("an abandoned probe must not answer later callers")
	}
}

// A login changes what `claude auth status` says without changing anything the
// report's cache key covers, so only an invalidation can reveal it.
func TestPluginInvalidationDropsThePreLoginCLIReport(t *testing.T) {
	InvalidateAuthCache()
	t.Cleanup(InvalidateAuthCache)
	previous := claudeAuthCommand
	t.Cleanup(func() { claudeAuthCommand = previous })
	loggedIn := "false"
	claudeAuthCommand = func(context.Context, string, string, map[string]string) (claudeCommandOutput, error) {
		return claudeCommandOutput{Stdout: []byte(`{"loggedIn":` + loggedIn + `,"apiProvider":"firstParty"}`)}, nil
	}
	var plugin ports.AgentAuthCacheInvalidator = &Plugin{}
	read := func() ports.AgentAuthStatus {
		t.Helper()
		report, ok := (&Plugin{}).claudeCLIAuthReport(context.Background(), "claude", "", nil)
		if !ok {
			t.Fatal("CLI report unavailable")
		}
		return report.status()
	}
	if got := read(); got != ports.AgentAuthStatusUnauthorized {
		t.Fatalf("before login = %q, want unauthorized", got)
	}
	loggedIn = "true"
	if got := read(); got != ports.AgentAuthStatusUnauthorized {
		t.Fatalf("within the cache window = %q, want the cached report", got)
	}
	plugin.InvalidateAuthCache()
	if got := read(); got != ports.AgentAuthStatusConfigured {
		t.Fatalf("after invalidation = %q, want configured", got)
	}
}

import { describe, expect, it } from "vitest";

import { composerDeliveryPresentation, composerDeliveryRoute, composerPrimaryAction, hardwareReturnIntent } from "./composerDeliveryModel";

describe("mobile chat delivery", () => {
	it("queues ordinary sends while a turn is active", () => {
		expect(composerDeliveryRoute("send", true)).toBe("queue");
		expect(composerDeliveryPresentation({ active: true, canSteer: true, hasDraft: true, hasAttachments: false, hasQueued: false })).toEqual({
			placeholder: "Send after this…",
			showSteerAction: true,
		});
	});

	it("steers only an explicit eligible text-only draft", () => {
		expect(composerDeliveryRoute("steer", true)).toBe("steer");
		expect(composerDeliveryRoute("steer", false)).toBe("queue");
		expect(composerDeliveryPresentation({ active: true, canSteer: true, hasDraft: true, hasAttachments: true, hasQueued: false }).showSteerAction).toBe(false);
		expect(composerDeliveryPresentation({ active: true, canSteer: true, hasDraft: true, hasAttachments: false, hasQueued: true }).showSteerAction).toBe(false);
	});

	it("keeps the idle composer free of queue controls", () => {
		expect(composerDeliveryPresentation({ active: false, canSteer: true, hasDraft: true, hasAttachments: false, hasQueued: false })).toEqual({
			placeholder: "Message this worker…",
			showSteerAction: false,
		});
	});

	it("uses the primary composer control to stop only when active and empty", () => {
		expect(composerPrimaryAction({ active: true, hasDraft: false, hasAttachments: false })).toBe("stop");
		expect(composerPrimaryAction({ active: true, hasDraft: true, hasAttachments: false })).toBe("send");
		expect(composerPrimaryAction({ active: true, hasDraft: false, hasAttachments: true })).toBe("send");
		expect(composerPrimaryAction({ active: false, hasDraft: false, hasAttachments: false })).toBe("send");
	});

	it("maps hardware Return to the desktop composer's send and steer keys", () => {
		const none = { command: false, control: false, option: false };
		expect(hardwareReturnIntent(none)).toBe("send");
		expect(hardwareReturnIntent({ ...none, option: true })).toBe("send");
		expect(hardwareReturnIntent({ ...none, command: true })).toBe("steer");
		expect(hardwareReturnIntent({ ...none, control: true })).toBe("steer");
		// Cmd+Return on a draft that cannot steer (attachments, quotes, idle turn) still sends.
		expect(composerDeliveryRoute(hardwareReturnIntent({ ...none, command: true }), false)).toBe("queue");
	});
});

import { act, create, type ReactTestRenderer } from "react-test-renderer";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("expo-router", () => ({ Stack: { SearchBar: "StackSearchBar" } }));
vi.mock("../ThemeProvider", () => ({ useTheme: () => ({ highlight: "highlight", textPrimary: "text", textTertiary: "hint", accent: "accent" }) }));

import { ComposerSearchField } from "./ComposerSearchField";

let renderer: ReactTestRenderer | undefined;
beforeEach(() => {
	vi.stubGlobal("IS_REACT_ACT_ENVIRONMENT", true);
	const error = console.error;
	vi.spyOn(console, "error").mockImplementation((...args) => {
		if (String(args[0]).startsWith("react-test-renderer is deprecated")) return;
		error(...args);
	});
});
afterEach(() => {
	act(() => renderer?.unmount());
	renderer = undefined;
	vi.restoreAllMocks();
	vi.unstubAllGlobals();
});

function render(initialQuery: string) {
	const onQuery = vi.fn();
	act(() => { renderer = create(<ComposerSearchField initialQuery={initialQuery} placeholder="Search skills" onQuery={onQuery} />); });
	return { onQuery, bar: () => renderer!.root.findByType("StackSearchBar" as never) };
}

describe("iOS composer search", () => {
	it("searches in the navigation bar, filtering in place", () => {
		const { bar, onQuery } = render("");
		expect(bar().props.placeholder).toBe("Search skills");
		act(() => bar().props.onChangeText({ nativeEvent: { text: "rev" } }));
		expect(onQuery).toHaveBeenLastCalledWith("rev");
		act(() => bar().props.onCancelButtonPress());
		expect(onQuery).toHaveBeenLastCalledWith("");
	});

	// The header hands the bar's commands over on every render of the bar; only
	// the first may write, or the user's typing would be replaced.
	it("opens on the composer's query, once", () => {
		const { bar } = render("rev");
		const commands = { setText: vi.fn() };
		bar().props.ref.current = commands;
		bar().props.ref.current = null;
		bar().props.ref.current = commands;
		expect(commands.setText).toHaveBeenCalledExactlyOnceWith("rev");
		expect(bar().props.ref.current).toBe(commands);
	});
});

import { describe, expect, it } from "vitest";
import { materialDrawableNames } from "./toolbarIcon.types";

import {
	ARCHIVE_SESSION_HINT,
	ARCHIVE_SESSION_CONFIRM,
	workerAccessibilityActions,
	workerActionNamed,
	workerActionSymbols,
	workerContextActions,
	type WorkerActionId,
	type WorkerActionState,
} from "./worker-action-model";

const ALL_ACTIONS: readonly WorkerActionId[] = ["open", "pin", "unpin", "rename", "resume", "restore", "openPr", "delete"];

const state = (over: Partial<WorkerActionState> = {}): WorkerActionState => ({
	pinned: false,
	terminated: false,
	stopped: false,
	hasPr: false,
	...over,
});

const ids = (over: Partial<WorkerActionState> = {}) => workerContextActions(state(over)).map((a) => a.id);

describe("workerContextActions", () => {
	it("offers the always-available actions on a plain running worker", () => {
		expect(ids()).toEqual(["open", "pin", "rename", "delete"]);
	});

	it("flips pin to unpin for a pinned worker", () => {
		expect(ids({ pinned: true })).toContain("unpin");
		expect(ids({ pinned: true })).not.toContain("pin");
	});

	it("offers the pull request only when there is one", () => {
		const action = workerContextActions(state({ hasPr: true })).find((item) => item.id === "openPr");
		expect(action).toEqual({ id: "openPr", title: "Review pull request" });
		expect(ids()).not.toContain("openPr");
	});

	// The chat screen already makes this choice: a terminated AO session is
	// restored, a merely stopped agent is resumed. Offering both would push that
	// distinction onto the user.
	it("offers resume for a stopped agent and restore for a terminated session", () => {
		expect(ids({ stopped: true })).toContain("resume");
		expect(ids({ stopped: true })).not.toContain("restore");
		expect(ids({ terminated: true })).toContain("restore");
		expect(ids({ terminated: true })).not.toContain("resume");
	});

	it("prefers restore when a session is both terminated and stopped", () => {
		expect(ids({ terminated: true, stopped: true })).toContain("restore");
		expect(ids({ terminated: true, stopped: true })).not.toContain("resume");
	});

	// Regression fence: there is no stop or pause endpoint. kill() is what Delete
	// calls, so a "stop" entry would be a second name for the same destructive
	// action.
	it("never offers an action without an endpoint behind it", () => {
		const everything = [
			...ids(),
			...ids({ pinned: true, hasPr: true, stopped: true }),
			...ids({ terminated: true, hasPr: true }),
		];
		expect(everything).not.toContain("stop");
		expect(everything).not.toContain("pause");
	});

	// Archive calls killSession, which deletes a clean worktree folder.
	it("keeps Archive last and marks it as the only destructive action", () => {
		for (const over of [{}, { pinned: true, hasPr: true }, { terminated: true }]) {
			const actions = workerContextActions(state(over));
			expect(actions.at(-1)).toEqual({ id: "delete", title: "Archive session", destructive: true });
			expect(actions.filter((a) => a.destructive)).toHaveLength(1);
		}
	});

	it("confirms Archive with desktop's wording", () => {
		expect(ARCHIVE_SESSION_CONFIRM).toEqual({
			title: "Are you sure you want to archive this session?",
			message: "You can always restore it from the Archive section later.",
			cancel: "No",
			confirm: "Confirm",
		});
		// Short enough for the two lines iOS's menu gives a subtitle.
		expect(ARCHIVE_SESSION_HINT).toBe("Stops the agent. Keeps uncommitted work.");
	});

	it("opens with Open, so the menu's first item is the row's own tap", () => {
		expect(ids({ terminated: true, hasPr: true, pinned: true })[0]).toBe("open");
	});
});

describe("workerAccessibilityActions", () => {
	// A screen reader can neither swipe a row open nor long-press it, so the
	// menu's actions have to be the row's own accessibility actions.
	it("offers every menu action but Open, which is the row's activation", () => {
		const actions = workerContextActions(state({ hasPr: true, stopped: true }));
		expect(workerAccessibilityActions(actions)).toEqual([
			{ name: "resume", label: "Resume agent" },
			{ name: "pin", label: "Pin" },
			{ name: "rename", label: "Rename" },
			{ name: "openPr", label: "Review pull request" },
			{ name: "delete", label: "Archive session" },
		]);
	});

	it("routes only the actions the row offers", () => {
		const actions = workerContextActions(state());
		expect(workerActionNamed(actions, "delete")).toBe("delete");
		expect(workerActionNamed(actions, "activate")).toBeUndefined();
		expect(workerActionNamed(actions, "restore")).toBeUndefined();
	});
});

describe("workerActionSymbols", () => {
	// Android's menu takes a bundled drawable, and a missing file is a
	// bundle-time failure rather than a blank icon, so every action's Material
	// Symbol has to be one the shared registry bundles (lib/toolbarIcon.test.ts
	// checks its files).
	it.each(ALL_ACTIONS)("draws %s's Material Symbol from the shared drawable registry", (id) => {
		expect(materialDrawableNames).toContain(workerActionSymbols[id].android);
	});
});

package terminalui

import (
	"strings"
	"testing"
)

func TestPlainTerminalTextStripsControlsAndPreservesVisibleRows(t *testing.T) {
	input := "\x1b[2mfirst\x1b[0m\r\n\x1b]8;;https://example.com\x1b\\second\x1b]8;;\x1b\\"
	if got, want := PlainTerminalText(input), "first\n\nsecond"; got != want {
		t.Fatalf("PlainTerminalText() = %q, want %q", got, want)
	}
}

func TestLastPromptIsEmptyOrDimPlaceholder(t *testing.T) {
	tests := []struct {
		name   string
		output string
		marker string
		want   bool
	}{
		{name: "blank claude", output: "status\n\x1b[39m❯\u00a0", marker: "❯", want: true},
		{name: "dim claude placeholder", output: "\x1b[39m❯\u00a0\x1b[2mclean up this code\x1b[0m", marker: "❯", want: true},
		{name: "typed claude draft", output: "\x1b[39m❯\u00a0do not submit this", marker: "❯", want: false},
		{name: "claude permission option", output: "permission\n❯ 1. Yes\n  2. No", marker: "❯", want: false},
		{name: "dim codex placeholder", output: "› \x1b[2mExplain this codebase\x1b[0m\n\n\x1b[2mmodel · workspace\x1b[0m", marker: "›", want: true},
		{name: "plain codex placeholder fails closed", output: "› Explain this codebase\nmodel · workspace", marker: "›", want: false},
		{name: "wrapped human draft fails closed", output: "❯\nhuman draft\nfooter", marker: "❯", want: false},
		{name: "leading blank rows in human draft fail closed", output: "❯\n\nhuman draft", marker: "❯", want: false},
		{name: "historical prompt is outside lookback", output: "❯\n1\n2\n3\n4\n5\n6\n7\n8\n9", marker: "❯", want: false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := LastPromptIsEmptyOrDimPlaceholder(tt.output, tt.marker); got != tt.want {
				t.Fatalf("LastPromptIsEmptyOrDimPlaceholder() = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestLastPromptComposerState(t *testing.T) {
	tests := []struct {
		name   string
		output string
		want   ComposerState
	}{
		{name: "missing prompt", output: "provider starting", want: ComposerUnknown},
		{name: "empty", output: "\x1b[39m❯\u00a0", want: ComposerEmpty},
		{name: "dim placeholder", output: "❯ \x1b[2mAsk a question\x1b[0m", want: ComposerEmpty},
		{name: "draft", output: "❯ keep this draft", want: ComposerDraft},
		{name: "wrapped draft", output: "❯\nkeep this draft", want: ComposerDraft},
		{name: "truecolor draft", output: "❯ \x1b[38;2;246;226;183mkeep this draft", want: ComposerDraft},
