		t.Fatal("overwrote conflicting model route")
	}
	after, _ := os.ReadFile(path)
	if string(after) != string(before) {
		t.Fatal("changed Qwen settings after conflict")
	}
}

func TestQwenProviderAddsTheRouteEndpointToAnExistingModel(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "qwen")
	t.Setenv("QWEN_HOME", dir)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, "settings.json")
	if err := os.WriteFile(path, []byte(`{"modelProviders":{"openai":[{"id":"or-model","envKey":"OPENROUTER_API_KEY"}]}}`), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := saveQwenProvider(t.Context(), "OPENROUTER_API_KEY", "or-model"); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var settings struct {
		ModelProviders struct {
			OpenAI []struct {
				ID      string `json:"id"`
				BaseURL string `json:"baseUrl"`
			} `json:"openai"`
		} `json:"modelProviders"`
	}
	if err := json.Unmarshal(data, &settings); err != nil || len(settings.ModelProviders.OpenAI) != 1 || settings.ModelProviders.OpenAI[0].BaseURL != "https://openrouter.ai/api/v1" {
		t.Fatalf("Qwen settings = %s, %v", data, err)
	}
}

package agentauth

import "testing"

func TestSetJSONCEditsOnlyTheChangedValue(t *testing.T) {
	for _, tc := range []struct {
		name, in, want string
		path           []string
	}{
		{
			name: "replace",
			in:   "{\n  // keep\n  \"a\": {\"b\": \"old\" /* x */},\n}\n",
			path: []string{"a", "b"},
			want: "{\n  // keep\n  \"a\": {\"b\": \"new\" /* x */},\n}\n",
		},
		{
			name: "insert into an existing object",
			in:   "{\"a\": {\"c\": 1} // note\n}",
			path: []string{"a", "b"},
			want: "{\"a\": {\"c\": 1, \"b\":\"new\"} // note\n}",
		},
		{
			name: "create missing parents",
			in:   "{\"x\": 1}",
			path: []string{"a", "b"},
			want: "{\"x\": 1, \"a\":{\"b\":\"new\"}}",
		},
		{
			name: "empty object",
			in:   "{}",
			path: []string{"a"},
			want: "{\"a\":\"new\"}",
		},
		{
			name: "keeps a BOM",
			in:   "\ufeff{\"a\": \"old\"}",
			path: []string{"a"},
			want: "\ufeff{\"a\": \"new\"}",
		},
		{
			name: "string that looks like a comment",
			in:   "{\"u\": \"http://x//y\", \"a\": \"old\"}",
			path: []string{"a"},
			want: "{\"u\": \"http://x//y\", \"a\": \"new\"}",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, err := setJSONC([]byte(tc.in), tc.path, []byte(`"new"`))
			if err != nil || string(got) != tc.want {
				t.Fatalf("setJSONC = %q, %v; want %q", got, err, tc.want)
			}
			var parsed map[string]any
			if err := jsoncUnmarshal(got, &parsed); err != nil {
				t.Fatalf("result does not parse: %v", err)
			}
		})
	}
	if _, err := setJSONC([]byte(`{"a": [1]}`), []string{"a", "b"}, []byte(`"new"`)); err == nil {
		t.Fatal("descended into a non-object")
	}
}

